fn score(report: *const Report) usize { return report.line_solves + 25 * report.guesses; }
fn rankLess(_: void, a: *Report, b: *Report) bool { if (a.difficulty != b.difficulty) return @intFromEnum(a.difficulty) < @intFromEnum(b.difficulty); if (score(a) != score(b)) return score(a) < score(b); return std.mem.order(u8, a.puzzle.name, b.puzzle.name) == .lt; }
const PuzzleOutputs = struct { reports: []const *Report, solutions: C.Lines, stats: C.Lines };
fn processPuzzles(blocks: []const C.Strings) PuzzleOutputs {
    var earlier: std.StringHashMapUnmanaged(void) = .empty; var reports: std.ArrayList(*Report) = .empty; var solutions: C.Lines = .{}; var stats: C.Lines = .{}; stats.write("puzzle,status,difficulty,width,height,givens,simple_known,logic_known,line_solves,guesses,max_depth,solutions,answer"); var invalid: usize = 0;
