    std.mem.sort(*Report, ranked.items, {}, rankLess); var ranking: C.Lines = .{}; ranking.write("RANKING"); for (ranked.items, 1..) |report, i| ranking.add("rank {d} {s} {s} score={d} size={d}x{d}", .{ i, report.puzzle.name, difficultyText(report.difficulty), score(report), report.puzzle.width, report.puzzle.height }); solutions.paragraph(ranking); var summary: C.Lines = .{}; summary.add("SUMMARY puzzles={d} invalid={d} contradiction={d} none={d} unique={d} multiple={d} easy={d} medium={d} hard={d} line_solves={d} guesses={d}", .{ blocks.len, invalid, statuses[0], statuses[1], statuses[2], statuses[3], difficulties[0], difficulties[1], difficulties[2], line_solves, guesses }); solutions.paragraph(summary); return .{ .reports = reports.items, .solutions = solutions, .stats = stats };
}
fn validatePicture(name: []const u8, rows: C.Strings, earlier: std.StringHashMapUnmanaged(void)) ?[]const u8 { if (!validName(name)) return "bad name"; if (earlier.contains(name)) return "duplicate name"; if (rows.len < 1 or rows.len > 30) return "bad height"; const width = rows[0].len; for (rows, 1..) |row, i| { if (row.len < 1 or row.len > 30 or row.len != width or !validStates(row, false)) return C.fmt("bad row {d}", .{i}); } return null; }
